import itertools
import random
import json
import sys
from problems import ThreeSat, ThreeColoring
from reduce import reduce


def sat_bruteforce(instance):
    m = instance["num_vars"]
    clauses = instance["clauses"]
    # iterate over all assignments 0/1 for each var (False/True)
    for bits in itertools.product([False, True], repeat=m):
        ok = True
        for clause in clauses:
            clause_ok = False
            for lit in clause:
                var = abs(lit) - 1
                val = bits[var]
                if lit > 0 and val:
                    clause_ok = True
                    break
                if lit < 0 and not val:
                    clause_ok = True
                    break
            if not clause_ok:
                ok = False
                break
        if ok:
            return True
    return False


def coloring_bruteforce(instance):
    n = instance["n"]
    edges = instance["edges"]
    for colors in itertools.product([0,1,2], repeat=n):
        good = True
        for u,v in edges:
            if colors[u] == colors[v]:
                good = False
                break
        if good:
            return True
    return False


def generate_random_sat(max_vars=4, max_clauses=5):
    m = random.randint(0, max_vars)
    # ensure each clause has three distinct vars and no var appears both signs
    clauses = []
    num_clauses = random.randint(0, max_clauses)
    for _ in range(num_clauses):
        if m < 3:
            # cannot create a valid clause, break
            break
        vars = random.sample(range(1, m+1), 3)
        clause = []
        for v in vars:
            lit = v if random.choice([True, False]) else -v
            clause.append(lit)
        clauses.append(clause)
    return {"num_vars": m, "clauses": clauses}


def run_tests(num_tests=200):
    passed = 0
    for i in range(num_tests):
        inst = generate_random_sat()
        # validate
        ThreeSat.validate(inst)
        sat_ans = sat_bruteforce(inst)
        graph = reduce(inst)
        ThreeColoring.validate(graph)
        col_ans = coloring_bruteforce(graph)
        if sat_ans == col_ans:
            passed += 1
        else:
            print("Mismatch on instance", inst)
            print("SAT answer", sat_ans, "Coloring answer", col_ans)
            print("Reduced graph", graph)
            break
    return passed, num_tests

if __name__ == "__main__":
    passed, total = run_tests(200)
    result = {"verified": passed == total, "tests_run": total, "tests_passed": passed}
    print(json.dumps(result, indent=2))
    with open("verdict.json", "w") as f:
        json.dump(result, f)
EOF"}

